import { defineConfig } from 'tsup'

/**
 * Only `validate` is bundled. The rest of this package's dist is codegen —
 * manifest.json, schema.json and a hand-emitted index.js of pure data — which
 * build.ts writes directly and a bundler would only get in the way of.
 */
export default defineConfig({
  entry: ['src/validate.ts'],
  outDir: 'dist',
  format: ['esm'],
  dts: true,
  // schema.json is generated by build.ts into the same dist this writes to;
  // inlining it keeps the validator a single import with no load-order puzzle.
  loader: { '.json': 'json' },
})
